-- New Tinkertown: the Crushcog Battle Suits walk their patrols.
--
-- Each of the eleven 42226 spawns holds a line and walks it end to end and back,
-- 65 to 111 yd, at walk speed with no pause at a node. Six were on random wander
-- at 3 yd and five stood still; none had a path.
--
-- `waypoint_data` loops, so an out-and-back line is written out in full -- nodes
-- 1..N then N-1..2 -- and rotated so point 1 is the node the spawn stands on.
-- Without the rotation the suit walks the length of its own route on respawn.
--
-- Path ids are guid * 10 and each spawn gets a `creature_addon` row to name one.
-- A spawn addon replaces the 42226 template addon outright rather than merging
-- with it, so SheathState 1 is repeated on every row.

DELETE FROM `waypoint_data` WHERE `id` IN (1685810,1680480,1685260,1677690,1679120,1685290,1685230,1675780,1685300,1680500,1683480);
DELETE FROM `creature_addon` WHERE `guid` IN (168581,168048,168526,167769,167912,168529,168523,167578,168530,168050,168348);


UPDATE `creature` SET `MovementType`=2, `wander_distance`=0 WHERE `guid` IN (168581,168048,168526,167769,167912,168529,168523,167578,168530,168050,168348);
